using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "EnemyTargetEnum", menuName = "Data/Battle/Enums/Target/Enemy Target Enum")]
public class EnemyTargetEnum : TargetEnum
{
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	public override void PopulateTargetInstanceLists()
	{
		base.inputManager.AddEnemiesToTargetInstanceList();
	}

	public override void AfterPopulateTargetInstanceLists()
	{
		TargetInstance componentInChildren = currentCorruptedAnimals.activeCorruptedAnimals.First().GetComponentInChildren<TargetInstance>();
		List<TargetInstance> horizontalTargetInstanceList = ReferenceSingleton<InputManager>.Instance.horizontalTargetInstanceList;
		if (horizontalTargetInstanceList.Contains(componentInChildren))
		{
			ReferenceSingleton<InputManager>.Instance.SetHorizontalIndex(horizontalTargetInstanceList.IndexOf(componentInChildren));
		}
	}
}
